import React, { Component } from 'react'
import { connect } from 'react-redux'
import { withRouter } from 'react-router'
import moment from 'moment'
import { Empty, Pagination, Spin, Button } from 'antd'
import PolicyActions from '../../../redux/policy/actions'
import CustomerActions from '../../redux/customer/actions'
import ClaimActions from '../../redux/claims/actions'
import { DisplaySearchResultStyle } from './displaySearchResult.style'
import PermissionChecker from '../../../components/permissionCheckerV2'

const {
  getInsuranceData,
  getInsuranceCountData
} = PolicyActions
const {
  searchCustomer
} = CustomerActions
const {
  searchClaimList
} = ClaimActions

class DisplaySearchResult extends Component {
  onClickDetail = (data) => {
    const { type } = this.props

    switch (type) {
      case 'user':
        return this.props.history.push({ pathname: `/customer/${data}` })
      case 'policy':
        return this.props.history.push({ pathname: `/policy/${data.id}` })
      default:
        return this.props.history.push({ pathname: `/claims/${data}` })
    }
  }

  onChangePagination = (page) => {
    const { searchText, searchKey, type } = this.props
    switch (type) {
      case 'policy':
        return this.props.getInsuranceData({ [searchKey]: searchText, offset: (page - 1) * 10 })
      case 'user':
        if (searchKey === 'mobileNo') {
          return this.props.searchCustomer({ 'phone': searchText, offset: (page - 1) * 10 })
        }
        return this.props.searchCustomer({ [searchKey]: searchText, offset: (page - 1) * 10 })
      default:
        return this.props.searchClaimList({ query: { [searchKey]: searchText, page, page_size: 10 } })
    }
  }

  displayUserResult = () => {
    const { data } = this.props
    return data && data.length > 0
      ? data.map(user => <div className='data-card'>
        <div><b>Name:</b> {user.name}</div>
        <div><b>Email:</b> {user.email}</div>
        <div><b>Phone Number:</b> {user.phone}</div>
        <PermissionChecker requiredPermission='ops.customer_detail'>
          <Button
            type={'primary'}
            className='detail-button'
            onClick={() => this.onClickDetail(user.userid)}>
            {'Details'}
          </Button>
        </PermissionChecker>
      </div>
      )
      : <Empty />
  }

  displayPolicyResult = () => {
    const { data } = this.props

    return data && data.length > 0
      ? data.map(policy => <div className='data-card'>
        <div><b>Application Number:</b> {policy.ApplicationNo}</div>
        <div><b>Insurance Policy Number:</b> {policy.InsurancePolicyNo}</div>
        <div><b>Insured:</b> {policy.Name}, {policy.Email}, {policy.MobileNo}</div>
        <Button
          type={'primary'}
          className='detail-button'
          onClick={() => this.onClickDetail({ partner: policy.Partner, id: policy.InternalID })}>
          {'Details'}
        </Button>
      </div>
      )
      : <Empty />
  }

  displayClaimResult = () => {
    const { data } = this.props

    return data && data.length > 0
      ? data.map(claim => <div className='data-card'>
        <div><b>Claim Number:</b> {claim.claim_number}</div>
        <div><b>Order Id:</b> {claim.order_id}</div>
        <div><b>Created At:</b> {moment(claim.created_at).format('DD/MM/YYYY hh:mm')}</div>
        <div><b>Details:</b> {claim.name}, {claim.email}, {claim.phone_number}</div>
        <Button
          type={'primary'}
          className='detail-button'
          onClick={() => this.onClickDetail(claim.claim_id)}>
          {'Details'}
        </Button>
      </div>
      )
      : <Empty />
  }

  displayPagination = () => {
    const { paginationData = {} } = this.props

    return <Pagination
      total={paginationData.total_records || paginationData.total}
      onChange={this.onChangePagination}
    />
  }

  render () {
    const { heading, type, customerSearchLoading, policyListLoading, searchClaimListLoading } = this.props

    return (
      <DisplaySearchResultStyle>
        <div className='heading'>
          {heading}
        </div>
        <Spin spinning={(!!customerSearchLoading && type === 'user') || (!!policyListLoading && type === 'policy') || (!!searchClaimListLoading && type === 'claim')}>
          {
            type === 'user'
              ? this.displayUserResult()
              : type === 'policy'
                ? this.displayPolicyResult()
                : this.displayClaimResult()
          }
        </Spin>
        <div className='pagination'>
          {this.displayPagination()}
        </div>
      </DisplaySearchResultStyle>
    )
  }
}

const WrappedDisplaySearchResult = withRouter(DisplaySearchResult)

export default connect(
  state => ({
    policyListLoading: state.Loading.GET_INSURANCE_DATA,
    customerSearchLoading: state.Loading.SEARCH_CUSTOMER,
    searchClaimListLoading: state.Loading.SEARCH_CLAIM_LIST
  }), {
    getInsuranceData,
    getInsuranceCountData,
    searchCustomer,
    searchClaimList
  })(WrappedDisplaySearchResult)
