import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Card, Input, notification, Radio } from 'antd'
import PolicyActions from '../../../redux/policy/actions'
import CustomerActions from '../../redux/customer/actions'
import ClaimActions from '../../redux/claims/actions'
import DisplaySearchResult from './displaySearchResult'

const Search = Input.Search
const plainOptions = [
  { 'text': 'Name', 'value': 'name' },
  { 'text': 'Email', 'value': 'email' },
  { 'text': 'Phone Number', 'value': 'mobileNo' },
  { 'text': 'Policy Number', 'value': 'insurancePolicyNo' },
  { 'text': 'Application Number', 'value': 'applicationNo' },
  { 'text': 'Claim Number', 'value': 'claim_number' },
  { 'text': 'Order Id', 'value': 'order_id' }
]

const {
  searchCustomer,
  resetStateCustomer
} = CustomerActions
const {
  getInsuranceData,
  getInsuranceCountData
} = PolicyActions
const {
  searchClaimList
} = ClaimActions

class Customer extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      searchKey: 'name',
      searchText: '',
      searchClicked: false
    }
  }

  componentDidMount () {
    const queryValues = new URLSearchParams(this.props.location.search)
    if (queryValues.get('message') && queryValues.get('select')) {
      this.setState({ searchKey: queryValues.get('select') },
        () => this.onClickSearch(queryValues.get('message')))
    }
  }

  onResultClick = (id, type) => {
    if (type === 'core_claim') {
      this.onClaimClick(id)
    } else if (type === 'insurances') {
      this.onPolicyClick(id, 'internalID')
    } else {
      this.onCustomerClick(id)
    }
  }

  onChangeCheck = e => {
    const value = e.target.value
    this.setState({ searchKey: value, searchClicked: false })
  }

  onClickSearch = value => {
    const { searchKey } = this.state

    if (value !== '') {
      this.setState({ searchClicked: true, searchText: value })
      switch (searchKey) {
        case 'insurances':
          this.props.getInsuranceData({ insurancePolicyNo: value })
          this.props.getInsuranceCountData({ insurancePolicyNo: value })
          return ''
        case 'applicationNo':
          this.props.getInsuranceData({ [searchKey]: value })
          this.props.getInsuranceCountData({ [searchKey]: value })
          return ''
        case 'claim_number':
        case 'order_id':
          this.props.searchClaimList({ query: { [searchKey]: value } })
          return ''
        case 'mobileNo':
          this.props.searchCustomer({ 'phone': value })
          this.props.getInsuranceData({ [searchKey]: value })
          this.props.getInsuranceCountData({ [searchKey]: value })
          this.props.searchClaimList({ query: { 'phone_number': value, page_size: 10 } })
          return ''
        default:
          this.props.searchCustomer({ [searchKey]: value })
          this.props.getInsuranceData({ [searchKey]: value })
          this.props.getInsuranceCountData({ [searchKey]: value })
          this.props.searchClaimList({ query: { [searchKey]: value, page_size: 10 } })
          return ''
      }
    } else {
      notification['error']({
        message: 'Please input something'
      })
    }
  }

  render () {
    const {
      customerResult,
      policyResult,
      policyMetaResult,
      searchClaimData = {}
    } = this.props
    const {
      searchText,
      searchKey,
      searchClicked
    } = this.state

    return (
      <Card>
        <Row type='flex' justify='center'>
          <Col sm={20} style={{ padding: '20px' }}>
            <center>
              <h3
                style={{
                  padding: '10px',
                  width: '220px',
                  marginBottom: '20px'
                }}
              >
                {'Explore Data Customer'}
              </h3>
              <label className='custom-label'>
                {'Find customer by input name, email, phone number, policy or \
                claim number on search bar'}
              </label>
              <Search
                placeholder='Input search text'
                enterButton='Search'
                size='large'
                value={searchText}
                onSearch={this.onClickSearch}
                onChange={e => this.setState({ searchText: e.target.value })}
                defaultValue={searchText}
              />
              <div>
                <Radio.Group onChange={this.onChangeCheck} defaultValue='name' value={searchKey}>
                  {plainOptions.map((option, index) =>
                    <Radio key={index} value={option.value}>{option.text}</Radio>
                  )}
                </Radio.Group>
              </div>
            </center>
          </Col>
        </Row>
        {
          searchClicked &&
          <Row type='flex'>
            {
              searchKey !== 'claim_number' && searchKey !== 'insurancePolicyNo' &&
              searchKey !== 'applicationNo' && searchKey !== 'order_id' &&
              <Col span={8} style={{ padding: '20px' }}>
                <DisplaySearchResult
                  type='user'
                  heading='Users'
                  data={customerResult.results}
                  paginationData={customerResult.metadata}
                  searchText={searchText}
                  searchKey={searchKey}
                />
              </Col>
            }
            {
              searchKey !== 'claim_number' && searchKey !== 'order_id' &&
              <Col span={8} style={{ padding: '20px' }}>
                <DisplaySearchResult
                  type='policy'
                  heading='Policies'
                  data={policyResult}
                  paginationData={policyMetaResult}
                  searchText={searchText}
                  searchKey={searchKey}
                />
              </Col>
            }
            {
              searchKey !== 'insurancePolicyNo' && searchKey !== 'applicationNo' &&
              <Col span={8} style={{ padding: '20px' }}>
                <DisplaySearchResult
                  type='claim'
                  heading='Claims'
                  data={searchClaimData.data}
                  paginationData={searchClaimData.meta_data}
                  searchText={searchText}
                  searchKey={searchKey}
                />
              </Col>
            }
          </Row>
        }
      </Card>
    )
  }
}

export default connect(
  state => ({
    customerResult: state.Customer.searchResult,
    policyResult: state.Policy.policyList,
    policyMetaResult: state.Policy.metadata,
    searchClaimData: state.Claims.searchClaimList
  }),
  {
    searchCustomer,
    resetStateCustomer,
    getInsuranceData,
    getInsuranceCountData,
    searchClaimList
  }
)(Customer)
